(function(){'use strict';
const $=id=>document.getElementById(id),model=new FlowEngine.Model(),view=new FlowView.View($('facility'),RevelystCAD);let running=!matchMedia('(prefers-reduced-motion: reduce)').matches,speed=1,follow=false,touring=false,tourT=0,tourIndex=0,drag=null,pinch=null,last=null,uiT=0,selected='AMR-07';const pointers=new Map(),tour=['site','inbound','locus','tower','vas','outbound'];
const names={travel:'Travel to pick',return:'Return loaded',pick:'Pick assist',induct:'Tote handoff','induct wait':'Induction queue','bridge wait':'Bridge queue'};
for(const b of model.bots){const o=document.createElement('option');o.value=b.id;o.textContent=b.id;$('bot-options').append(o);} $('select-agent').value=selected;
function size(){const r=$('viewport').getBoundingClientRect();view.resize(r.width,r.height,window.devicePixelRatio||1);view.fit(view.focus in FlowView.views?view.focus:'site');view.draw(model);}
function setCamera(key){follow=false;$('follow').setAttribute('aria-pressed','false');view.fit(key);$('view-name').textContent=FlowView.views[key].label;document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===key)));if(key==='inbound')select('ST-1');if(key==='locus')select('AMR-07');}
function select(id){selected=id;view.selection=id;$('select-agent').value=id;update();}
function locate(){const b=model.bots.find(x=>x.id===selected)||model.stretch.find(x=>x.id===selected);const s=Math.min(view.w/140,view.h/110,5);view.camera={s,x:view.w/2-b.x*s,y:view.h/2-b.y*s};view.focus='equipment';$('view-name').textContent=selected+' · close view';document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed','false'));}
function stopTour(){touring=false;$('tour').setAttribute('aria-pressed','false');$('tour').textContent='Guided tour';}
function zoom(f,x=view.w/2,y=view.h/2){stopTour();follow=false;$('follow').setAttribute('aria-pressed','false');const v=view.camera,p=view.world(x,y),s=Math.max(.35,Math.min(12,v.s*f));view.camera={s,x:x-p.x*s,y:y-p.y*s};}
$('play').onclick=()=>{running=!running;$('play').textContent=running?'Pause':'Play';$('play').setAttribute('aria-pressed',String(running));};$('play').textContent=running?'Pause':'Play';$('play').setAttribute('aria-pressed',String(running));
$('speed').onchange=()=>speed=Number($('speed').value);
$('reset').onclick=()=>{model.reset();stopTour();follow=false;$('follow').setAttribute('aria-pressed','false');document.querySelectorAll('[data-hold]').forEach(b=>b.setAttribute('aria-pressed','false'));update();view.draw(model);};
$('paths').onclick=e=>{view.paths=!view.paths;e.currentTarget.setAttribute('aria-pressed',String(view.paths));};$('depth').onclick=e=>{view.depth=!view.depth;view.cached=null;e.currentTarget.setAttribute('aria-pressed',String(view.depth));};
$('tour').onclick=()=>{touring=!touring;$('tour').setAttribute('aria-pressed',String(touring));$('tour').textContent=touring?'Stop tour':'Guided tour';if(touring){tourIndex=0;tourT=0;setCamera(tour[0]);}};
$('select-agent').onchange=e=>select(e.target.value);$('focus-agent').onclick=()=>{stopTour();follow=false;$('follow').setAttribute('aria-pressed','false');locate();};$('follow').onclick=()=>{stopTour();follow=!follow;$('follow').setAttribute('aria-pressed',String(follow));if(follow)locate();};
$('zoom-in').onclick=()=>zoom(1.35);$('zoom-out').onclick=()=>zoom(1/1.35);$('fit').onclick=()=>{stopTour();setCamera('site');};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{stopTour();setCamera(b.dataset.view);});
for(const b of document.querySelectorAll('[data-hold]'))b.onclick=()=>{b.setAttribute('aria-pressed',String(model.toggle(b.dataset.hold)));update();};$('clear').onclick=()=>{model.clear();document.querySelectorAll('[data-hold]').forEach(b=>b.setAttribute('aria-pressed','false'));update();};
for(const [button,dialog]of [['info','notes-dialog'],['reference','reference-dialog']]){$(button).onclick=()=>$(dialog).showModal();$(dialog).querySelector('[data-close]').onclick=()=>$(dialog).close();$(dialog).addEventListener('click',e=>{if(e.target===$(dialog))$(dialog).close();});}
const canvas=$('facility'),local=e=>{const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top};};
canvas.addEventListener('pointerdown',e=>{const p=local(e);pointers.set(e.pointerId,p);canvas.setPointerCapture(e.pointerId);stopTour();follow=false;$('follow').setAttribute('aria-pressed','false');$('tip').hidden=true;if(pointers.size===1){drag={...p,v:{...view.camera},moved:false};canvas.classList.add('dragging');}else{const [a,b]=[...pointers.values()];pinch={dist:Math.hypot(a.x-b.x,a.y-b.y)};drag=null;}});
canvas.addEventListener('pointermove',e=>{const p=local(e);if(pointers.has(e.pointerId))pointers.set(e.pointerId,p);if(pointers.size===2&&pinch){const[a,b]=[...pointers.values()],dist=Math.hypot(a.x-b.x,a.y-b.y);zoom(dist/Math.max(1,pinch.dist),(a.x+b.x)/2,(a.y+b.y)/2);pinch.dist=dist;}else if(drag){const dx=p.x-drag.x,dy=p.y-drag.y;view.camera.x=drag.v.x+dx;view.camera.y=drag.v.y+dy;if(Math.hypot(dx,dy)>4)drag.moved=true;}else{const b=view.hit(p.x,p.y,model);$('tip').hidden=!b;if(b){$('tip').textContent=b.id+' · '+(names[b.state]||FlowEngine.stretchPose(b.t).stage);$('tip').style.left=Math.min(view.w-190,p.x+14)+'px';$('tip').style.top=Math.max(5,p.y-32)+'px';}}});
canvas.addEventListener('pointerup',e=>{if(drag&&!drag.moved){const p=local(e),b=view.hit(p.x,p.y,model);if(b)select(b.id);}pointers.delete(e.pointerId);drag=null;pinch=null;canvas.classList.remove('dragging');});canvas.addEventListener('pointercancel',e=>{pointers.delete(e.pointerId);drag=null;pinch=null;canvas.classList.remove('dragging');});canvas.addEventListener('pointerleave',()=>{$('tip').hidden=true;});canvas.addEventListener('wheel',e=>{e.preventDefault();const p=local(e);zoom(Math.exp(-e.deltaY*.0015),p.x,p.y);},{passive:false});
canvas.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','+','=','-','Home',' '].includes(e.key)){e.preventDefault();stopTour();follow=false;$('follow').setAttribute('aria-pressed','false');if(e.key==='Home')setCamera('site');else if(e.key==='+'||e.key==='=')zoom(1.25);else if(e.key==='-')zoom(.8);else if(e.key===' ')$('play').click();else {view.camera.x+=e.key==='ArrowLeft'?45:e.key==='ArrowRight'?-45:0;view.camera.y+=e.key==='ArrowUp'?45:e.key==='ArrowDown'?-45:0;}}});
function update(){const b=model.bots.find(x=>x.id===selected),st=model.stretch.find(x=>x.id===selected);$('agent-name').textContent=selected;let state=b?names[b.state]:(model.flags.stretch&&selected==='ST-1'?'Intervention':FlowEngine.stretchPose(st.t).stage);$('agent-state').textContent=state;
 $('agent-description').textContent=b?b.state==='pick'?'The bot holds at the pick face while an associate transfers product into the tote.':b.state==='bridge wait'?'Waiting for access to the bridge linking north Locus pallets and S09–S12.':b.state==='induct wait'?'The loaded bot queues until induction can accept its tote.':b.state==='induct'?'The tote transfers from the robot to the conveyor. The robot then takes its next pick task.':b.loaded?'Loaded tote returns from the pick location to induction beside the tower.':'Travelling along the pick aisle to the next location. The route uses the supplied layout.':'Reach, grip, lift and deposit. Three active Stretch dock cells follow your latest markup; the total fleet is four.';
 $('travel').textContent=model.bots.filter(b=>['travel','return'].includes(b.state)).length;$('pick').textContent=model.bots.filter(b=>b.state==='pick').length;$('wait').textContent=model.bots.filter(b=>b.state.includes('wait')||b.state==='induct').length;
 $('handoff').textContent=model.items.length+' sample loads in conveyor / pack flow · '+model.stats.sorted+' sort handoffs this playback';
 const flags=Object.entries(model.flags).filter(([,v])=>v).map(([k])=>({stretch:'Stretch 01',conveyor:'Conveyor',bridge:'Bridge',lane:'Lane 6'})[k]);$('scene-status').textContent=flags.length?flags.join(' · ')+' held':'All process paths open';$('scene-status').classList.toggle('held',!!flags.length);
 $('hold-note').textContent=model.flags.conveyor?'Conveyors pause and loaded bots queue at induction. Clear the hold to release handoffs.':model.flags.bridge?'Bots pause before the bridge. Other pick routes remain available.':model.flags.lane?'Loads assigned to Lane 6 circulate until the lane is released.':model.flags.stretch?'Stretch 01 stops mid-cycle. The other two dock cells keep unloading.':'Watch queues and handoffs respond. Clear a hold to resume.';
 const ol=$('event-list');ol.replaceChildren(...model.events.slice(0,5).map(e=>{const li=document.createElement('li'),n=document.createElement('b'),t=document.createElement('span');n.textContent=String(e.n).padStart(2,'0');t.textContent=e.message;li.className=e.kind;li.append(n,t);return li;}));}
function loop(now){let dt=last===null?0:Math.min(.06,(now-last)/1000);last=now;if(!document.hidden){if(running){model.step(dt*speed);if(touring){tourT+=dt;if(tourT>9){tourT=0;tourIndex=(tourIndex+1)%tour.length;setCamera(tour[tourIndex]);}}}if(follow){const b=model.bots.find(x=>x.id===selected)||model.stretch.find(x=>x.id===selected),v=view.camera;v.x+=(view.w/2-b.x*v.s-v.x)*Math.min(1,dt*7);v.y+=(view.h/2-b.y*v.s-v.y)*Math.min(1,dt*7);}view.draw(model);FlowView.closeup($('closeup'),model,selected);uiT+=dt;if(uiT>.3){update();uiT=0;}}requestAnimationFrame(loop);}
new ResizeObserver(size).observe($('viewport'));size();update();requestAnimationFrame(loop);window.RevelystFlow={model,view,select,setCamera};
})();
